using System.Collections.Generic;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "AreaEnum", menuName = "Enums/AreaEnum")]
public class AreaEnum : ScriptableObject
{
	[SerializeField]
	private AreaEnviromentData areaEnviromentData;

	[SerializeField]
	private string areaString;

	[Header("Battle Setup")]
	public List<BattleCorruptedAnimals> ShuffleBattleCorruptedAnimals = new List<BattleCorruptedAnimals>();

	public List<BattleCorruptedAnimals> ShuffleHardBattleCorruptedAnimals = new List<BattleCorruptedAnimals>();

	[SerializeField]
	private AreaLevel[] areaLevels;

	public AreaEnviromentData AreaEnviromentData => areaEnviromentData;

	public string AreaString => areaString;

	public AreaLevel[] AreaLevels => areaLevels;

	public List<AreaLevel> GetAreaLevels(AreaLevelEnum areaLevelEnum)
	{
		List<AreaLevel> list = new List<AreaLevel>();
		for (int i = 0; i < areaLevels.Length; i++)
		{
			if (areaLevels[i].AreaLevelEnum == areaLevelEnum)
			{
				list.Add(areaLevels[i]);
			}
		}
		return list;
	}

	public List<BattleCorruptedAnimals> GetNormalBattleCorruptedAnimalsFromAreaLevelsButBoss()
	{
		List<BattleCorruptedAnimals> list = new List<BattleCorruptedAnimals>();
		for (int i = 0; i < areaLevels.Length - 1; i++)
		{
			list.AddRange(areaLevels[i].BattleCorruptedAnimals);
		}
		return list;
	}

	public List<BattleCorruptedAnimals> GetAllBattleCorruptedAnimals()
	{
		List<BattleCorruptedAnimals> list = new List<BattleCorruptedAnimals>();
		for (int i = 0; i < areaLevels.Length; i++)
		{
			list.AddRange(areaLevels[i].BattleCorruptedAnimals);
		}
		list.AddRange(ShuffleBattleCorruptedAnimals);
		list.AddRange(ShuffleHardBattleCorruptedAnimals);
		return list;
	}
}
